astroCode.globalCss:
@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --color-bg: #0B0B0C;
  --color-fg: #EFEAE1;
  --color-card: #141416;
  --color-card-fg: #FFFFFF;
  --color-primary: #D4AF37;
  --color-primary-fg: #0A0A0A;
  --color-accent: #5A7A64;
  --color-muted: #9E988F;
  --color-border: #292827;
  --font-heading: 'Shippori Mincho', serif;
  --font-body: 'Inter', sans-serif;
  --motion-easing: cubic-bezier(0.4, 0, 0.2, 1);
  --motion-dur-quick: 300ms;
  --motion-dur-std: 650ms;
  --motion-dur-slow: 1000ms;
  --btn-radius: rounded-xl;
  --card-radius: rounded-xl;
}

body {
  background-color: var(--color-bg);
  color: var(--color-fg);
  font-family: var(--font-body);
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  letter-spacing: -0.02em;
}

/* Studio Button Physics Grounded in Disney Principles (Anticipation & Squash/Stretch) */
.studio-btn-primary {
  background-color: var(--color-primary);
  color: var(--color-primary-fg);
  font-weight: 600;
  border-radius: var(--btn-radius);
  transition: all var(--motion-dur-quick) var(--motion-easing);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
  display: inline-flex;
  align-items: center;
  justify-content: center;


  background: linear-gradient(135deg, var(--color-primary) 0%, #F5E5A4 50%, var(--color-primary) 100%); box-shadow: 0 4px 20px rgba(212, 175, 55, 0.3);

}

.studio-btn-primary:hover {
  filter: brightness(1.12);
  transform: translateY(-2px);
}

.studio-btn-primary:active {
  transform: scale(0.97);
}

.studio-btn-secondary {
  border: 1px solid var(--color-border);
  color: var(--color-fg);
  font-weight: 500;
  border-radius: var(--btn-radius);
  background-color: rgba(255, 255, 255, 0.03);
  transition: all var(--motion-dur-quick) var(--motion-easing);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.studio-btn-secondary:hover {
  background-color: rgba(255, 255, 255, 0.08);
  border-color: var(--color-muted);
  transform: translateY(-1px);
}

/* Card Treatments */
.studio-card {
  background-color: var(--color-card);
  color: var(--color-card-fg);
  border-radius: var(--card-radius);
  border: 1px solid var(--color-border);
  transition: all var(--motion-dur-std) var(--motion-easing);



}

.studio-card:hover {
  transform: translateY(-4px); box-shadow: 0 20px 30px -10px rgba(0,0,0,0.4);



}

/* Ambient Layer Animations */
@keyframes studioAmbientFloat {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-8px); }
}

@keyframes studioAmbientPulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.02); opacity: 0.92; }
}

@keyframes studioZenBreathe {
  0%, 100% { transform: scale(1); opacity: 0.95; }
  50% { transform: scale(1.015); opacity: 1; }
}

.animate-studio-float {
  animation: studioAmbientFloat 6s ease-in-out infinite;
}

.animate-studio-pulse {
  animation: studioAmbientPulse 4s ease-in-out infinite;
}

.animate-studio-zen {
  animation: studioZenBreathe 8s ease-in-out infinite;
}

